<template>
  <div>
    <NavBarVue />
    <div class="card">
      <div class="card-body text-secondary">
        <b-row>
          <b-col lg="2" md="4" sm="12">
            <b-row>
              <b-col
                lg="12"
                md="12"
                sm="12"
                style="cursor: pointer; border-bottom: 1px solid black"
                class="mt-0"
                @click="selectPanel(1)"
                ><b-icon icon="people-fill"></b-icon> &nbsp;&nbsp;&nbsp;<b
                  >Usuários</b
                ></b-col
              >
              <b-col
                lg="12"
                md="12"
                sm="12"
                style="cursor: pointer; border-bottom: 1px solid black"
                class="mt-0"
                @click="selectPanel(4)"
                ><b-icon icon="credit-card-fill"></b-icon> &nbsp;&nbsp;&nbsp;<b
                  >Contas</b
                ></b-col
              >
              <b-col
                lg="12"
                md="12"
                sm="12"
                style="cursor: pointer; border-bottom: 1px solid black"
                class="mt-0"
                @click="selectPanel(2)"
                ><b-icon icon="pie-chart-fill"></b-icon> &nbsp;&nbsp;&nbsp;<b
                  >Taxa de juros</b
                ></b-col
              >
              <b-col
                lg="12"
                md="12"
                sm="12"
                style="cursor: pointer; border-bottom: 1px solid black"
                class="mt-0"
                @click="selectPanel(3)"
                ><b-icon icon="gear-fill"></b-icon> &nbsp;&nbsp;&nbsp;<b
                  >Configurações</b
                ></b-col
              >
            </b-row>
          </b-col>
          <b-col lg="10" md="8" sm="12">
            <UserComponent v-if="selectedPanel === 1" />
            <InterestRateComponent v-if="selectedPanel === 2" />
            <CompanyDetailsComponent v-if="selectedPanel === 3" />
            <AccountsComponent v-if="selectedPanel === 4" />
          </b-col>
        </b-row>
      </div>
    </div>
  </div>
</template>

<script>
import { mapGetters } from "vuex";

import NavBarVue from "@/components/NavBar";
import UserComponent from "@/components/settings/UserComponent";
import InterestRateComponent from "@/components/settings/InterestRateComponent";
import CompanyDetailsComponent from "@/components/settings/CompanyDetailsComponent";
import AccountsComponent from "@/components/settings/AccountsComponent";

export default {
  data: () => ({
    selectedPanel: 1,
  }),

  computed: {
    ...mapGetters(["user", "token", "company", "updatedPassword"]),
  },

  created() {
    this.checkPasswordStatus();
  },

  components: {
    NavBarVue,
    UserComponent,
    InterestRateComponent,
    CompanyDetailsComponent,
    AccountsComponent,
  },

  methods: {
    selectPanel(panel) {
      if (panel === 1) {
        this.selectedPanel = 1;
      } else if (panel === 2) {
        this.selectedPanel = 2;
      } else if (panel === 3) {
        this.selectedPanel = 3;
      } else if (panel === 4) {
        this.selectedPanel = 4;
      }
    },

    checkPasswordStatus() {
      this.user.updatedPassword == 1 ? "" : this.$router.replace("/profile");
    },
  },
};
</script>

<style scoped>
.card {
  width: 100%;
}

.table {
  font-size: 14px;
}

th {
  font-size: 10px;
  font-weight: bold;
}
</style>
