<template>
  <div>
    <b-row>
      <b-col lg="9" md="8" sm="10">
        <b-row class="mt-1 mb-2">
          <b-col cols="8" style="cursor: pointer; font-size: 12pt; font-weight: bold;"
            ><b>Tipos de financiamento: {{ interestRates.length }}</b></b-col
          >
          <b-col class="text-right">
            <b-badge
              @click="getAllRates()"
              variant="secondary"
              pill
              style="cursor: pointer; font-size: 12pt"
              ><b-icon icon="arrow-clockwise" aria-hidden="true"></b-icon>
              Refresh
            </b-badge>
          </b-col>
        </b-row>
        <b-overlay :show="isLoading" rounded="sm">
          <p class="text-danger text-center" v-if="interestRates.length == 0">
            <b>Sem nenhuma taxa de juros cadastrada até o momento.</b>
          </p>
          <table v-else class="table table-sm table-hover table-stripped">
            <thead>
              <tr style="font-size: 12pt" class="bg-secondary text-white">
                <th>Tipo de crédito</th>
                <th>Juros</th>
                <th>Taxa</th>
                <th class="text-center">Acções</th>
              </tr>
            </thead>
            <tbody>
              <tr
                v-for="tax in interestRates"
                :key="tax.id"
                style="font-size: 12pt; cursor: pointer"
                :class="{ 'bg-warning': form.id === tax.id }"
              >
                <td>{{ tax.name }}</td>
                <td>{{ tax.tax * 100 }}%</td>
                <td v-money-format="tax.administrativeFee"></td>
                <td>
                  <b-row>
                    <b-col class="text-center" @click="deleteTax(tax)"
                      ><b-icon icon="trash-fill" variant="danger"></b-icon
                    ></b-col>
                    <b-col class="text-center" @click="updateTax(tax)"
                      ><b-icon icon="pen-fill" variant="primary"></b-icon
                    ></b-col>
                  </b-row>
                </td>
              </tr>
            </tbody>
          </table>
        </b-overlay>
      </b-col>
      <b-col
        ><b style="font-size: 12pt; font-weight: bold;"><b-icon icon="plus-square" variant="secondary"></b-icon> Nova taxa</b>
        <hr class="bg-secondary mt-0" />
        <b-form-group label="Tipo de crédito" class="mt-0" label-for="input-1">
          <b-form-input
            v-model="form.name"
            size="sm"
            type="text"
            placeholder="Tipo de crédito"
            required
          ></b-form-input>
        </b-form-group>

        <b-form-group
          label="Preparos administrativo"
          class="mt-0"
          label-for="input-1"
        >
          <b-form-input
            v-model="form.administrativeFee"
            size="sm"
            type="number"
            step="any"
            placeholder="Preparos administrativo"
            required
          ></b-form-input>
        </b-form-group>

        <b-form-group label="Taxa de juros:" label-for="input-5">
          <b-form-select
            v-model="form.tax"
            size="sm"
            :options="taxis"
            required
          ></b-form-select>
        </b-form-group>
        <b-row>
          <b-col lg="6" md="6" sm="12" class="d-flex align-items-center">
            <b-button
              :disabled="isLoading"
              type="button"
              size="sm"
              block
              variant="danger"
              @click="resetFields()"
              ><b-icon icon="trash-fill"></b-icon> &nbsp;Reset</b-button
            >
          </b-col>
          <b-col lg="6" md="6" sm="12" class="d-flex align-items-center">
            <b-button
              :disabled="isLoading"
              type="submit"
              size="sm"
              block
              variant="success"
              @click="registerTax()"
              v-if="form.id == 0"
              >Enviar &nbsp;<b-icon icon="telegram"></b-icon
            ></b-button>
            <b-button
              :disabled="isLoading"
              type="submit"
              size="sm"
              block
              variant="success"
              @click="decidedToUpdateTax()"
              v-else
              >Actualizar &nbsp;<b-icon icon="telegram"></b-icon
            ></b-button>
          </b-col>
        </b-row>
      </b-col>
    </b-row>
    <b-modal hide-footer ref="delete-tax" title="Deletar">
      <p class="text-danger text-center">Deseja realmente excluir esta taxa?</p>
      <b-row>
        <b-col>
          <b-button block size="sm" @click="cancelDeletion()"
            >Cancelar</b-button
          >
        </b-col>
        <b-col>
          <b-button block size="sm" variant="danger" @click="decidedToDelete()"
            >Deletar</b-button
          >
        </b-col>
      </b-row>
    </b-modal>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import axios from "axios";
import logs from "@/utils/logs";

export default {
  name: "InterestRateComponent",

  data: () => ({
    form: {
      id: 0,
      name: "",
      tax: 0.3,
      administrativeFee: 0.0,
    },
    taxis: [
      { text: "5%", value: 0.05 },
      { text: "10%", value: 0.1 },
      { text: "15%", value: 0.15 },
      { text: "20%", value: 0.2 },
      { text: "25%", value: 0.25 },
      { text: "30%", value: 0.3 },
    ],
    taxDeletionId: 0,
    selectedTax: {},
  }),

  computed: {
    ...mapGetters(["isLoading", "user", "token", "company", "interestRates"]),
  },

  created() {},

  methods: {
    getAllRates() {
      this.$store.dispatch("getAllRates", this.company.id);
    },

    updateTax(tax) {
      this.form = tax;
    },

    decidedToUpdateTax() {
      if (this.form.name.length < 4) {
        this.showToast(
          "Aviso!",
          "warning",
          "O campo 'Tipo de crédito' é obrigatório."
        );
        return;
      } else {
        this.$store.commit("LOADING_STATUS", true);
        axios
          .put(`/api/rate/${this.form.id}`, this.form)
          .then((res) => {
            const data = res.data;
            if (data.success == true) {
              this.showToast("Sucesso!", "success", data.message);

              const logsParams = logs(
                this.user,
                `${this.form.name} com taxa de ${this.form.tax} actualizada com sucesso.`,
                "Actualização de taxa de juros"
              );
              this.$store.dispatch("addLog", logsParams);

              this.getAllRates();
              this.resetFields();
            } else {
              this.showToast("Erro!", "danger", data.message);
            }
            this.$store.commit("LOADING_STATUS", false);
          })
          .catch((err) => {
            this.$store.commit("LOADING_STATUS", false);
            this.showToast("Erro!", "danger", err.message);
          });
      }
    },

    registerTax() {
      if (this.form.name.length < 4) {
        this.showToast("Aviso!", "warning", "Tipo de crédito requerido");
        return;
      } else {
        this.$store.commit("LOADING_STATUS", true);
        this.form.companyId = this.company.id;
        axios
          .post("/api/rate", this.form)
          .then((res) => {
            const data = res.data;
            if (data.success == true) {
              this.showToast(
                "Sucesso!",
                "success",
                "Taxa adicionada com sucesso"
              );

              const logsParams = logs(
                this.user,
                `${this.form.name} com taxa de ${this.form.tax} cadastrada com sucesso.`,
                "Cadastro de taxa de juros"
              );
              this.$store.dispatch("addLog", logsParams);

              this.getAllRates();
            } else {
              this.showToast("Erro!", "danger", data.message);
            }

            this.$store.commit("LOADING_STATUS", false);
          })
          .catch((err) => {
            this.$store.commit("LOADING_STATUS", false);
            this.showToast("Erro!", "danger", err.message);
          });
      }
    },

    resetFields() {
      this.taxDeletionId = 0;
      this.form = {
        id: 0,
        name: "",
        tax: 0.3,
      };
    },

    decidedToDelete() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .delete(`/api/rate/${this.taxDeletionId}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);

            const logsParams = logs(
              this.user,
              `${this.selectedTax.name} excluída com sucesso.`,
              "Exclusão de taxas de juros"
            );
            this.$store.dispatch("addLog", logsParams);

            this.getAllRates();
          } else {
            this.showToast("Erro!", "warning", data.message);
          }
          this.cancelDeletion();
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.cancelDeletion();
          this.$store.commit("LOADING_STATUS", false);
          this.showToast("Erro!", "danger", err.message);
        });
    },

    deleteTax(tax) {
      this.taxDeletionId = tax.id;
      this.selectedTax = tax;
      this.$refs["delete-tax"].show();
    },

    cancelDeletion() {
      this.taxDeletionId = 0;
      this.$refs["delete-tax"].hide();
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },
  },
};
</script>
