<template>
  <div>
    <b-row>
      <b-col lg="10" md="8" sm="12">
        <b-row class="mt-1 mb-2">
          <b-col style="font-size: 12pt; font-weight: bold"
            ><b
              ><b-icon icon="credit-card-fill" aria-hidden="true"></b-icon
              >{{ " Contas: #" + accounts.length }}</b
            ></b-col
          >
          <b-col class="text-right">
            <b-badge
              @click="generateAccountNumber()"
              variant="secondary"
              pill
              style="cursor: pointer; font-size: 12pt"
              ><b-icon icon="plus-square" aria-hidden="true"></b-icon>
              Nova conta
            </b-badge>
          </b-col>
          <b-col class="text-right">
            <b-badge
              @click="getAllAccounts()"
              variant="secondary"
              pill
              style="cursor: pointer; font-size: 12pt"
              ><b-icon icon="arrow-clockwise" aria-hidden="true"></b-icon>
              Refresh
            </b-badge>
          </b-col>
        </b-row>
        <b-overlay :show="isLoading" rounded="sm">
          <p class="text-danger text-center" v-if="accounts.length == 0">
            <b>Contas indisponíveis.</b>
          </p>
          <table v-else class="table table-sm table-hover table-stripped">
            <thead>
              <tr style="font-size: 12pt" class="bg-secondary text-white">
                <th>Descrição</th>
                <th>Número</th>
                <th>Titular</th>
                <th class="text-center">Acções</th>
              </tr>
            </thead>
            <tbody>
              <tr
                v-for="account in accounts"
                :key="account.id"
                style="font-size: 12pt; cursor: pointer"
              >
                <td>{{ account.accountDescription }}</td>
                <td>{{ account.accountNumber }}</td>
                <td>{{ account.accountHolder }}</td>
                <td>
                  <b-row>
                    <b-col class="text-center" @click="deleteAccount(account)"
                      ><b-icon icon="trash-fill" variant="danger"></b-icon
                    ></b-col>
                    <b-col class="text-center" @click="updateAccount(account)">
                      <b-icon icon="pen-fill" variant="primary"></b-icon
                    ></b-col>
                  </b-row>
                </td>
              </tr>
            </tbody>
          </table>
        </b-overlay>
      </b-col>
      <b-col> </b-col>
    </b-row>
    <b-modal hide-footer ref="delete-account" title="Deletar">
      <p class="text-danger text-center">
        Deseja realmente excluir esta conta?
      </p>
      <b-row>
        <b-col>
          <b-button block size="sm" @click="cancelDeletion()"
            >Cancelar</b-button
          >
        </b-col>
        <b-col>
          <b-button block size="sm" variant="danger" @click="decidedToDelete()"
            >Deletar</b-button
          >
        </b-col>
      </b-row>
    </b-modal>

    <b-modal hide-footer ref="open-account" title="Adicionar nova conta">
      <b-form-group
        label="Digite a descrição da conta"
        class="mt-0"
        label-for="input-1"
      >
        <b-form-input
          v-model="form.accountDescription"
          size="sm"
          type="text"
          placeholder="Descrição da conta"
          required
        ></b-form-input>
      </b-form-group>

      <b-form-group label="Número da conta" label-for="input-2">
        <b-form-input
          v-model="form.accountNumber"
          size="sm"
          type="number"
          placeholder="Digite o número da conta"
          required
        ></b-form-input>
      </b-form-group>
      <b-form-group label="Titular da conta" label-for="input-2">
        <b-form-input
          v-model="form.accountHolder"
          size="sm"
          type="text"
          placeholder="Digite o titular da conta"
          required
        ></b-form-input>
      </b-form-group>
      <b-row>
        <b-col>
          <b-button block size="sm" variant="primary" @click="cancelAction()"
            >Cancelar</b-button
          >
        </b-col>
        <b-col>
          <b-button
            v-if="form.id > 0"
            block
            size="sm"
            variant="success"
            :disabled="isLoading"
            @click="submitUpdate()"
            ><b-icon icon="save" variant="primary"></b-icon>
            Actualizar</b-button
          >
          <b-button
            v-else
            block
            size="sm"
            variant="success"
            :disabled="isLoading"
            @click="createAccount()"
            ><b-icon icon="save" variant="primary"></b-icon> Gravar</b-button
          >
        </b-col>
      </b-row>
    </b-modal>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import axios from "axios";
import logs from "../../utils/logs";

export default {
  name: "AccountsComponent",

  data: () => ({
    form: {
      accountHolder: "",
      accountDescription: "",
      createdBy: "",
      updatedBy: "",
      accountNumber: "",
    },
    accountDeletionId: 0,
    filteredCustomers: [],
    accountSelected: {},
  }),

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "token",
      "company",
      "accounts",
      "customers",
    ]),
  },

  created() {
    this.form.createdBy = this.user.name;
    this.form.updatedBy = this.user.name;
    this.form.companyId = this.company.id;
    this.getAllAccounts();
  },

  methods: {
    getAllAccounts() {
      this.$store.dispatch("getAllAccounts", this.company.id);
    },

    generateAccountNumber() {
      this.$refs["open-account"].show();
    },

    updateAccount(account) {
      this.form = account;
      this.$refs["open-account"].show();
    },

    cancelAction() {
      this.$refs["open-account"].hide();
    },

    submitUpdate() {
      if (this.form.accountDescription.length < 3) {
        this.showToast("Aviso!", "warning", "Digite a descrição da conta.");
        return;
      } else if (this.form.accountNumber.length < 9) {
        this.showToast(
          "Aviso!" + this.form.accountNumber.length,
          "warning",
          "Digite um número de conta válido."
        );
        return;
      } else {
        this.$store.commit("LOADING_STATUS", true);
        axios
          .put(`/api/account/${this.form.id}`, this.form)
          .then((res) => {
            const data = res.data;
            if (data.success == true) {
              this.showToast("Sucesso!", "success", data.message);
              const logsParams = logs(
                this.user,
                `${this.form.accountNumber} actualizada com sucesso.`,
                "Actualização de conta"
              );
              this.$store.dispatch("addLog", logsParams);
              this.resetFields();
              this.getAllAccounts();
            } else {
              this.showToast("Erro!", "danger", data.message);
              this.resetFields();
            }
            this.$store.commit("LOADING_STATUS", false);
          })
          .catch((err) => {
            this.$store.commit("LOADING_STATUS", false);
            this.showToast("Erro!", "danger", err.message);
            this.resetFields();
          });
      }
    },

    createAccount() {
      if (this.form.accountDescription.length < 3) {
        this.showToast("Aviso!", "warning", "Digite a descrição da conta.");
        return;
      } else if (this.form.accountNumber.length < 9) {
        this.showToast(
          "Aviso!" + this.form.accountNumber.length,
          "warning",
          "Digite um número de conta válido."
        );
        return;
      } else {
        this.$store.commit("LOADING_STATUS", true);
        axios
          .post("/api/account", this.form)
          .then((res) => {
            const data = res.data;
            if (data.success == true) {
              this.showToast("Sucesso!", "success", data.message);
              const logsParams = logs(
                this.user,
                `${this.form.accountNumber} criada com sucesso.`,
                "Cadastro de conta"
              );
              this.$store.dispatch("addLog", logsParams);
              this.resetFields();
              this.getAllAccounts();
            } else {
              this.showToast("Erro!", "danger", data.message);
              this.resetFields();
            }
            this.$store.commit("LOADING_STATUS", false);
          })
          .catch((err) => {
            this.$store.commit("LOADING_STATUS", false);
            this.showToast("Erro!", "danger", err.message);
            this.resetFields();
          });
      }
    },

    resetFields() {
      this.form.accountDeletionId = 0;
      this.form.accountHolder = "";
      this.form.accountDescription = "";
      this.form.accountNumber = "";
      this.$refs["open-account"].hide();
    },

    decidedToDelete() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .delete(`/api/account/${this.accountDeletionId}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);

            const logsParams = logs(
              this.user,
              `${this.accountSelected.accountNumber} excluída com sucesso.`,
              "Exclusão de conta"
            );
            this.$store.dispatch("addLog", logsParams);
            this.getAllAccounts();
          } else {
            this.showToast("Erro!", "warning", data.message);
          }
          this.cancelDeletion();
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.cancelDeletion();
          this.$store.commit("LOADING_STATUS", false);
          this.showToast("Erro!", "danger", err.message);
        });
    },

    deleteAccount(account) {
      this.accountDeletionId = account.id;
      this.accountSelected = account;
      this.$refs["delete-account"].show();
    },

    cancelDeletion() {
      this.accountDeletionId = 0;
      this.$refs["delete-account"].hide();
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },
  },
};
</script>
